static void code_matches(ProcessReader& r,uint64_t rva,const std::string& value){auto expected=unhex(value);require(r.read(r.base+rva,expected.size())==expected,"Reviewed code bytes changed");}
static void virtual_matches(ProcessReader& r,uint64_t object,size_t offset,uint64_t rva){require(r.at<uint64_t>(r.at<uint64_t>(object)+offset)==r.base+rva,"Reviewed current virtual target changed");}
