for(auto rva:{0x5ef7800ull,0x56f0e70ull,0x3b847b0ull,0x4236c80ull,0x1505900ull,0x3b82890ull,0x3b82920ull}){std::ostringstream name;name<<"protocol_function_"<<std::hex<<rva<<".bin";frozen_code_matches(owner,r,rva,name.str());}frozen_code_matches(owner,r,0x4733960,"protocol_fragment_4733960.bin",160);frozen_code_matches(owner,r,0x41861f0,"protocol_fragment_41861f0.bin",8);
